	@Override
	public void onTick() {
		if (mc.level == null || mc.player == null) return;
		if (tickCounter-- > 0) return;
		tickCounter = scanInterval.getInt();
		rescan();
	}

	/** Scans now (also used by the tests). */
	public void rescan() {
		if (mc.level == null || mc.player == null) return;
		List<BlockEntity> found = BlockEntityScanner.scan(mc.level, mc.player.getEyePosition(), range.get(), be -> {
			Kind k = kindOf(be);
			return k != null && enabled.get(k).isOn();
		});
		List<Target> out = new ArrayList<>();
		Set<BlockPos> skip = new HashSet<>();
		Map<Kind, Integer> c = new EnumMap<>(Kind.class);
		int max = maxTargets.getInt();
		if (mc.level != shulkerLevel) { shulkerLevel = mc.level; knownShulkers.clear(); }
		Target near = null;
		double nd = Double.MAX_VALUE;
		for (BlockEntity be : found) {
			BlockPos pos = be.getBlockPos();
			if (skip.contains(pos)) continue;
			Kind k = kindOf(be);
			BlockState state = be.getBlockState();
			AABB box = shapeBox(state, pos);
			if (mergeDoubleChests.isOn() && (k == Kind.CHEST || k == Kind.TRAPPED_CHEST) && state.hasProperty(ChestBlock.TYPE)
				&& state.getValue(ChestBlock.TYPE) != ChestType.SINGLE) {
				Direction d = ChestBlock.getConnectedDirection(state);
				BlockPos other = pos.relative(d);
				BlockState os = mc.level.getBlockState(other);
				if (os.getBlock() == state.getBlock()) {
					box = box.minmax(shapeBox(os, other));
					skip.add(other);
				}
			}
			c.merge(k, 1, Integer::sum);
			Target t = new Target(box, k, colorFor(be, k), pos);
			if (out.size() < max) out.add(t);
			double d = box.getCenter().distanceToSqr(mc.player.position());
			if (d < nd) { nd = d; near = t; }
			if (k == Kind.SHULKER && shulkerAlert.isOn() && knownShulkers.add(pos.immutable())) shulkerFound(pos);
		}
		targets = out;
		if (near == null) nearest(null, null, 0);
		else nearest(near.box().getCenter(), near.kind().label, near.rgb());
		synchronized (counts) { counts.clear(); counts.putAll(c); }
	}

	private AABB shapeBox(BlockState state, BlockPos pos) {
		VoxelShape shape = state.getShape(mc.level, pos);
		AABB b = shape.isEmpty() ? new AABB(0, 0, 0, 1, 1, 1) : shape.bounds();
		return b.move(pos.getX(), pos.getY(), pos.getZ());
	}

	private int colorFor(BlockEntity be, Kind k) {
		if (k == Kind.SHULKER && shulkerColorMode.is("Dye Color") && be instanceof ShulkerBoxBlockEntity s) {
			DyeColor dye = s.getColor();
			if (dye == null) return 0x9B6BB0;   // undyed shulker box
			return dye.getTextureDiffuseColor() & 0xFFFFFF;
		}
		return -1;   // resolved per frame from the colour setting (it may be a rainbow)
	}

	/** Adds this frame's highlights (render thread). */
	public void collect(List<Highlight> out) {
		if (!isEnabled()) return;
		HighlightStyle st = style();
		boolean showLabels = labels.isOn();
		for (Target t : targets) {
			ColorSetting cs = colors.get(t.kind());
			int rgb = t.rgb() >= 0 ? t.rgb() : cs.rgb((t.pos().getX() + t.pos().getZ()) * 0.02f);
			String label = null;
			if (showLabels) {
				label = t.kind().label;
				if (labelDistance.isOn() && mc.player != null)
					label += " " + Math.round(Math.sqrt(t.pos().distToCenterSqr(mc.player.position()))) + "m";
			}
			out.add(new Highlight(t.box(), rgb, st, label));
		}
	}

